require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';api_v2_require_enabled();if($_SERVER['REQUEST_METHOD']!=='POST')api_v2_error('POST required',405);$in=api_input();$challenge=trim((string)($in['challenge']??''));$code=trim((string)($in['code']??''));if($challenge===''||$code==='')api_v2_error('Challenge and code are required.',422);$q=db()->prepare("SELECT c.id challenge_id,c.user_id,c.expires_at,u.name,u.email,u.phone,u.role,u.status FROM mobile_api_challenges c JOIN users u ON u.id=c.user_id WHERE c.challenge_hash=? AND c.consumed_at IS NULL AND c.expires_at>NOW() LIMIT 1");$q->execute([hash('sha256',$challenge)]);$u=$q->fetch();if(!$u||!security_verify_otp((int)$u['user_id'],$code,'mobile_api_v2'))api_v2_error('Invalid or expired verification code.',422);db()->prepare('UPDATE mobile_api_challenges SET consumed_at=NOW() WHERE id=?')->execute([(int)$u['challenge_id']]);$user=['id'=>(int)$u['user_id'],'name'=>$u['name'],'email'=>$u['email'],'phone'=>$u['phone'],'role'=>$u['role']];$auth=api_v2_issue_session($user,$in);security_record_login(true,(string)($u['email']??''),(int)$u['user_id'],'mobile_v2');api_v2_ok(['two_factor_required'=>false,'auth'=>$auth,'user'=>api_v2_user_public($user),'app_type'=>api_v2_app_type($in)],(int)$u['user_id']);
